/**
 * Recomputes a header's Status__c from the status of its child lines whenever a
 * line's Line_Status__c changes.
 */
public without sharing class LSORollupService {

    public static void rollupHeaderStatus(Set<Id> headerIds) {
        if (headerIds == null || headerIds.isEmpty()) {
            return;
        }

        Map<Id, List<String>> statusesByHeader = new Map<Id, List<String>>();
        for (Id hId : headerIds) {
            statusesByHeader.put(hId, new List<String>());
        }

        for (LSO_CCAR_Line__c ln : [
            SELECT Id, Line_Status__c, LSO_Cross_Country_Access_Request__c
            FROM LSO_CCAR_Line__c
            WHERE LSO_Cross_Country_Access_Request__c IN :headerIds
        ]) {
            statusesByHeader.get(ln.LSO_Cross_Country_Access_Request__c).add(ln.Line_Status__c);
        }

        List<LSO_Cross_Country_Access_Request__c> toUpdate = new List<LSO_Cross_Country_Access_Request__c>();
        for (Id hId : statusesByHeader.keySet()) {
            toUpdate.add(new LSO_Cross_Country_Access_Request__c(
                Id = hId,
                Status__c = computeStatus(statusesByHeader.get(hId))
            ));
        }
        if (!toUpdate.isEmpty()) {
            Database.update(toUpdate, false);
        }
    }

    @TestVisible
    private static String computeStatus(List<String> lineStatuses) {
        if (lineStatuses == null || lineStatuses.isEmpty()) {
            return 'Draft';
        }

        Boolean hasDraft = false;
        Boolean hasPending = false;
        Boolean hasApproved = false;
        Boolean hasRejected = false;

        for (String s : lineStatuses) {
            if (s == 'Draft') {
                hasDraft = true;
            } else if (s == 'Pending') {
                hasPending = true;
            } else if (s == 'Approved') {
                hasApproved = true;
            } else if (s == 'Rejected') {
                hasRejected = true;
            }
        }

        if (hasPending) {
            return 'In Review';
        }
        if (!hasDraft && hasApproved && !hasRejected) {
            return 'Fully Approved';
        }
        if (!hasDraft && hasRejected && !hasApproved) {
            return 'Rejected';
        }
        if (!hasDraft && hasApproved && hasRejected) {
            return 'Partially Approved';
        }
        return 'Draft';
    }
}
